def subsetsProductK(nums: list[int], k: int) -> int:
    count = 0
    def dfs(idx, curr_prod, picked):
        nonlocal count
        if idx == len(nums):
            if picked and curr_prod < k:
                count += 1
            return
        dfs(idx + 1, curr_prod, picked)
        if curr_prod * nums[idx] < k:
            dfs(idx + 1, curr_prod * nums[idx], True)
    dfs(0, 1, False)
    return count

